@datatype class BatteryConfidenceOwner_Operational_Api (
  val id: Art.BridgeId,
  val evidenceIn_Id : Art.PortId,
  val stateToCharge_Id : Art.PortId,
  val stateToReadiness_Id : Art.PortId,
  val confidenceToFault_Id : Art.PortId,
  val stateToComposition_Id : Art.PortId,
  val stateToHazard_Id : Art.PortId) extends BatteryConfidenceOwner_Api {

  // Logika spec var representing port state for incoming data port
  @spec var evidenceIn: Drone_Lifecycle_Energy_Governor.BatteryEvidence = $

  def get_evidenceIn() : Option[Drone_Lifecycle_Energy_Governor.BatteryEvidence] = {
    Contract(
      Ensures(
        Res == Some(evidenceIn)
      )
    )
    val value : Option[Drone_Lifecycle_Energy_Governor.BatteryEvidence] = Art.getValue(evidenceIn_Id) match {
      case Some(Drone_Lifecycle_Energy_Governor.BatteryEvidence_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port evidenceIn.  Expecting 'Drone_Lifecycle_Energy_Governor.BatteryEvidence_Payload' but received ${v}")
        None[Drone_Lifecycle_Energy_Governor.BatteryEvidence]()
      case _ => None[Drone_Lifecycle_Energy_Governor.BatteryEvidence]()
    }
    return value
  }
